/**
 * Embeds src/reading/prompts/**\/*.md into src/reading/prompts/generated.ts so the built server carries the
 * prompts without reading files at runtime (tsc does not copy .md). Run: node scripts/embed-prompts.mjs
 * `--check` exits 1 if the generated file is stale (used by a unit test and CI).
 */
import { createHash } from 'node:crypto';
import { readdirSync, readFileSync, writeFileSync, existsSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const dir = path.join(root, 'src', 'reading', 'prompts');
const out = path.join(dir, 'generated.ts');

function listMd(base, prefix = '') {
  const names = [];
  for (const e of readdirSync(path.join(base, prefix), { withFileTypes: true })) {
    if (e.isDirectory()) names.push(...listMd(base, path.join(prefix, e.name)));
    else if (e.name.endsWith('.md')) names.push(path.join(prefix, e.name));
  }
  return names.sort();
}

const files = listMd(dir);
const entries = files.map((f) => {
  const key = f.replace(/\\/g, '/').replace(/\.md$/, '');
  const text = readFileSync(path.join(dir, f), 'utf8').replace(/\r\n/g, '\n').trimEnd();
  return [key, text];
});
const version = createHash('sha256').update(entries.map(([k, t]) => `${k}\n${t}`).join('\n--\n')).digest('hex').slice(0, 12);

const body =
  `/* eslint-disable */\n// GENERATED by scripts/embed-prompts.mjs from src/reading/prompts/**/*.md. Do not edit by hand.\n` +
  `export const PROMPT_VERSION = ${JSON.stringify(version)};\n` +
  `export const PROMPTS: Record<string, string> = ${JSON.stringify(Object.fromEntries(entries), null, 2)};\n`;

if (process.argv.includes('--check')) {
  const current = existsSync(out) ? readFileSync(out, 'utf8').replace(/\r\n/g, '\n') : '';
  if (current !== body) {
    console.error('src/reading/prompts/generated.ts is stale; run: node scripts/embed-prompts.mjs');
    process.exit(1);
  }
  console.log('prompts up to date', version);
} else {
  writeFileSync(out, body);
  console.log('wrote', path.relative(root, out), 'version', version, 'files', files.length);
}
